import { defineConfig } from "vite";
import vue from "@vitejs/plugin-vue";
import AutoImport from "unplugin-auto-import/vite";
import { resolve } from "node:path";

// Library build: produces dist/index.js (ESM), dist/index.cjs (CJS),
// dist/index.d.ts (types, generated by vue-tsc) and dist/style.css.
export default defineConfig({
  plugins: [vue(), AutoImport({ imports: ["vue"], dts: false })],
  build: {
    lib: {
      entry: resolve(__dirname, "src/index.ts"),
      formats: ["es", "cjs"],
      fileName: (format) => (format === "es" ? "index.js" : "index.cjs"),
    },
    cssCodeSplit: false,
    emptyOutDir: false, // types (dist/index.d.ts) are emitted by vue-tsc first
    rollupOptions: {
      external: ["vue", "naive-ui", /^@tiptap\//, "@remixicon/vue"],
      output: {
        exports: "named",
        // inline all CSS variables/component styles into one style.css
        assetFileNames: "style.[ext]",
      },
    },
  },
});
